{"type":"match","data":{"path":{"text":"www.canada.ca/Band-tailed Pigeon (Patagioenas fasciata) COSEWIC assessment and status report 2021.txt"},"lines":{"text":"Criterion A (Decline in Total Number of Mature Individuals): Not applicable. Estimated 11.5% decline in number of mature individuals over the past three generations (13 years), based on the Breeding Bird Survey, does not meet thresholds.\n"},"line_number":247,"absolute_offset":16919,"submatches":[{"match":{"text":"Mature Individuals"},"start":40,"end":58},{"match":{"text":"mature individuals"},"start":114,"end":132}]}}
